SELECT round(sum(v),2) AS openrank,uniqExactIf(tuple(platform,repo_id),v>0) AS positive_repositories FROM (SELECT e.platform AS platform,e.repo_id AS repo_id,e.created_at AS month,any(e.openrank) AS v FROM global_openrank e INNER JOIN (SELECT DISTINCT platform,entity_id,entity_type FROM flatten_labels WHERE type='Foundation' AND startsWith(id,':foundations/linux_foundation')) l ON (l.entity_id=e.repo_id AND l.entity_type='Repo' AND l.platform=e.platform) OR (l.entity_id=e.org_id AND l.entity_type='Org' AND l.platform=e.platform) WHERE e.platform IN ('GitHub','Gitee','GitLab','AtomGit') AND e.type='Repo' AND e.created_at>='2025-07-01' AND e.created_at<'2026-07-01' GROUP BY e.platform,e.repo_id,e.created_at) SETTINGS max_execution_time=80,max_threads=4;